text:
{
  "entries": [
    {
      "name_han": "择吉汇要",
      "logic_thesis": "吉日选择必须综合年月日时与神煞方位，以天干地支五行生克为骨，以黄道黑道、建除十二神为用，使人事动作与天时同步，方可趋吉避凶。",
      "logic_chain": "1) 人事成败系于时机，时机由干支气运决定；2) 日家神煞分宜忌，黄道宜行、黑道宜止；3) 用事类别（嫁娶、动土、开市等）各有专神与禁忌；4) 年月时方若与日神相冲克，则吉日亦凶；5) 汇通诸家口诀去芜存精，以统一可检之式择日；6) 最终以“事—时—方—人”四合为断。",
      "logic_practice": "1) 定用事类型与五行属性；2) 排出年命、用事干支与黄道日；3) 查建除、十二直、岁破月破与忌神；4) 核对方位与太岁、三煞；5) 取干支相生合、神煞相扶之日时下事。",
      "logic_compare": "较《选择金鉴》更偏实用汇编而非理论纠偏；较《董氏诹吉新书》少个人创说、多诸家汇要；与钦定修造书相比，覆盖用事更广而不专于修造吉方。"
    },
    {
      "name_han": "选择金鉴诹吉述正",
      "logic_thesis": "择吉之学久为术家附会所乱，须以经典正统与理气正法为镜，驳伪存真，使诹吉回归阴阳五行与天文历法之正轨。",
      "logic_chain": "1) 民间择日书多杂伪神、妄忌，导致无所适从；2) 正法本于干支、节气、星历与理气，非凭空神煞；3) 以“金鉴”对照诸说，辨何者为经、何者为伪；4) 述正者：宜忌须能自洽于五行生克与天道运行；5) 校正后形成可复核之择吉程序；6) 目的在正学术、利民用而非炫奇。",
      "logic_practice": "1) 先立用事与命主干支；2) 只用经证神煞与正忌，弃无传妄忌；3) 以月建、日辰、时辰理气论生克；4) 用天文历法校验黄道黑道；5) 凡无理气自洽之忌则不取。",
      "logic_compare": "与《择吉汇要》之“汇”相对，本书重在“正”；较钦定官修更偏学术辨伪；较《董氏诹吉新书》更强调驳杂归正而非新创体系。"
    },
    {
      "name_han": "钦定修造吉方立成选择书",
      "logic_thesis": "修造动土关乎国计民生，吉方与吉日必须依钦定成法立成表查，使方位、岁运、神煞与工程步骤严格对应，不得私意变更。",
      "logic_chain": "1) 修造扰动土气与宅命，须合岁运；2) 太岁、三煞、五黄等方忌为硬约束；3) 吉方随年、月、日流转，当用立成表速查；4) 择日与择方一体：日吉而方凶则仍凶；5) 官修统一标准可防民间异说致误；6) 按工序（动土、上梁、安门等）分阶选择。",
      "logic_practice": "1) 定修造年命与坐向；2) 查本年太岁、三煞、五黄凶方；3) 用立成表取当月吉方；4) 再选合山向与命主之黄道日时；5) 动土、起工各阶段分别复核忌方。",
      "logic_compare": "较《择吉汇要》专深于修造吉方；较《选择金鉴》重制度成法而非辨伪论理；与《董氏诹吉新书》比，权威在钦定立成而非私家新说。"
    },
    {
      "name_han": "董氏诹吉新书",
      "logic_thesis": "诹吉当在旧法基础上以新例、新断重订宜忌，使选择更贴合实际用事与当代历用，避免泥古而不通。",
      "logic_chain": "1) 旧择日书体例驳杂、互有矛盾；2) 董氏以一己经验与理法重编神煞主次；3) 新书强调用事分类细化与日时配合；4) 主张以干支气运为纲、神煞为目；5) 对陈说或存或废，以效验与自洽为准；6) 形成可操作之“新”选择流程。",
      "logic_practice": "1) 按董氏用事门类定需查项目；2) 以年命、日主与用事五行定喜忌；3) 依新订神煞表取吉日；4) 合参时辰与方位；5) 遇旧忌与新断冲突时从新书主法。",
      "logic_compare": "较《择吉汇要》更有作者体系色彩；较《选择金鉴》少官方正统辩驳、多私家重订；与钦定修造书比，范围更广而权威性属民间术数。"
    },
    {
      "name_han": "灵台秘苑",
      "logic_thesis": "天文星历为人事休咎之上源，观象于灵台、推步于秘法，可使灾祥、分野、时令与军国大事相应可测。",
      "logic_chain": "1) 天象变动必应地事（天人感应）；2) 星官、分野划定区域与人事对应；3) 日食、月变、彗孛、五星犯守各有占辞；4) 推步须密（秘苑）方能先机；5) 占与历结合：定时刻后方定应事；6) 结论服务于趋避与决策而非空言。",
      "logic_practice": "1) 记录当前日辰与节气；2) 查五星、日月、异常天象；3) 以分野定应地；4) 对照占辞判吉凶等级；5) 将应期落实到干支日时以指导行止。",
      "logic_compare": "较择日专书更重星象本源；与《天元玉历祥异赋》同属灾祥天文系统，但《灵台秘苑》偏观象制度与星占体系，赋体书偏歌诀记诵；较八字命理更宏观、更重天象即时占。"
    },
    {
      "name_han": "天元玉历祥异赋",
      "logic_thesis": "天地祥异皆有可赋可诵之象理，以歌赋统摄灾异占验，使天元气运之常变能被快速识别并对应人事吉凶。",
      "logic_chain": "1) 天元气运有常有变，变为祥异；2) 祥异类别（云气、日晕、星变等）各含信息；3) 赋体浓缩占辞，便于记诵检索；4) 象现→类推→应人应地应期；5) 吉象宜顺势、凶象宜修省趋避；6) 玉历之意在授时与警世并行。",
      "logic_practice": "1) 辨所现祥异属于何门；2) 据赋文取占断要点；3) 结合发生方位与节令；4) 推应期干支与所应人事；5) 以修省、改作或择时应对凶异。",
      "logic_compare": "与《灵台秘苑》同出天文灾异传统，本书以赋体便于口传；较择吉书不主选日程式而主象占；对八字实践而言，可补“岁运天象”一层外证。"
    },
    {
      "name_han": "埋忧集",
      "logic_thesis": "忧患与非常之事埋藏于日常因果之中，通过志怪叙事揭示德行、欲念与命运转折的隐秘逻辑，使人以智慎消未形之忧。",
      "logic_chain": "1) 表层为奇闻，深层为劝惩；2) 祸常起于一念一举之失序；3) 超常情节用来放大道德与气运规则；4) 埋忧者：先见微知著方可埋藏未来之忧；5) 叙事结局提供可迁移的处世推理；6) 读故事即演练对“兆—应”结构的识别。",
      "logic_practice": "1) 从命局找“忧根”（忌神、空亡、刑冲）；2) 看大运流年何时引动该根；3) 以事类对应神煞与十神；4) 用改运行为（择时、避方、修德）压未发之忧；5) 验证应期是否与叙事式因果同构。",
      "logic_compare": "与《里乘》《益智录》同属清代笔记志怪劝惩传统；较《虞初新志》更个人化、忧世色彩更重；非择日专书，其逻辑在于以事验理，可与命理“事应”互参。"
    },
    {
      "name_han": "里乘",
      "logic_thesis": "乡里见闻中的非常事件遵循可推的因果与报应结构，借“里中之说”证明天理不远、人事有征，从而训练由微知著的判断力。",
      "logic_chain": "1) 材料取自近密可核的乡里传闻；2) 奇事背后是伦理与气数的连锁；3) 善恶、诚伪在关键节点触发转折；4) 叙述强调证据感与过程感，近似推演；5) 读者由个案抽象为处世与察人之法；6) 里乘即载道之乘，非徒猎奇。",
      "logic_practice": "1) 将个案要素映射为用神/忌神关系；2) 标出触发点（岁运、人事、方位）；3) 重建“因→机→果”三步链；4) 在盘中定位同类结构；5) 对未来流年做预防性选择。",
      "logic_compare": "与《埋忧集》《益智录》同为清人说部志异，但更强调里巷可信性；较《虞初新志》之选家总集，本书作者意识与劝惩更集中；对择吉书而言，提供“事理应验”样本而非日课公式。"
    },
    {
      "name_han": "益智录",
      "logic_thesis": "录奇所以益智：非常之闻被整理为可学的智识，使人增长察几、处变、知命与自省的推理能力。",
      "logic_chain": "1) 智不生于空理而生于对事变的归纳；2) 异闻是极端条件下的人性与气运实验；3) 整理编排使散事成可检索之教训；4) 读者由事得法：见兆、判势、决策；5) 益智最终落实为避害取利的理性行为；6) 故志怪与实用智慧同构。",
      "logic_practice": "1) 提取故事中的关键变量（时、地、人、德、欲）；2) 转为命理变量（干支、十神、神煞）；3) 练习快速判断“当下宜动/宜静”；4) 设计最小成本的趋避步骤；5) 事后复盘以增强应期感。",
      "logic_compare": "题旨较《埋忧集》更明示“益智”；与《里乘》同走以事推理路线；较《虞初新志》范围与体例更专于益智劝惩，而非广收文言小说之美。"
    },
    {
      "name_han": "虞初新志",
      "logic_thesis": "广采当代传奇与实录体文言，在“奇而可传”的标准下保存人事变幻之逻辑样本，使读者于文学鉴赏中同步获得世情与命运的比较推理。",
      "logic_chain": "1) 虞初传统即“小说家”采异；2) 新志重在明清近事与可读性；3) 选文标准含奇、真、文三者张力；4) 各篇独立却共享命运无常与因果主题；5) 汇编形成跨阶层、跨地域的案例库；6) 理智训练来自比较阅读而非单一教条。",
      "logic_practice": "1) 分类阅读（科第、情义、冤报、异技等）；2) 每类抽象为命理事论模块；3) 对照八字格局中的同类象；4) 用多篇比较修正单一神煞迷信；5) 将“可传之奇”还原为可检之条件组合。",
      "logic_compare": "作为总集，比《埋忧集》《里乘》《益智录》更博杂、文学性更强；不提供择日公式，而提供丰富事应语料；与天文择吉经典相比，逻辑重心在人文因果与叙事推理，而非历法神煞。"
    }
  ]
}
